# Shot list for "The Great White Shark Has One Weakness. Orcas Found It". Executed by build.py.
PI = 3.14159
def orc(path, len=700, **k): return dict(k="orca", path=path, len=len, **k)
def shk(path, len=560, **k): return dict(k="shark", path=path, len=len, **k)
def HOLD(x0, x1, y, d, len=820, slen=560, **k): return [orc([[0, x0, y], [d, x1, y + 20]], len, beat=0.45, **k), shk(None, slen, heldBy=0, roll=PI, limp=1)]
